# builtin-redirect.sh - redirections on builtins and functions
# (Iteration 255). They were parsed and then ignored: `read x < file`
# read the shell's own input, `pwd > f` wrote to the terminal, and a
# function's redirections did nothing. A redirection that cannot be
# opened is reported and the command does not run.
d=/tmp/relf-diff-redir.$$
mkdir -p "$d"
cd "$d"
printf 'l1\nl2\nl3\n' > in.txt
read x < in.txt
echo "x=$x"
read a b < in.txt
echo "a=$a b=$b"
pwd > p.txt
echo "p-ok=$(test "$(cat p.txt)" = "$(pwd)" && echo yes)"
echo appended >> p.txt
sed 1d p.txt
echo to-err 2>e.txt >&2
echo "e=$(cat e.txt)"
f() { echo "in f $1"; echo "f-err" >&2; }
f a > fo.txt 2> fe.txt
echo "fo=$(cat fo.txt) fe=$(cat fe.txt)"
g() {
  f inner > gi.txt
  echo "g-out"
}
g > go.txt
echo "go=$(cat go.txt) gi=$(cat gi.txt)"
read y < /nonexistent/file
echo "st=$? y=[$y]"
pwd > /nonexistent/dir/file
echo "st=$?"
echo still-here
cd / > /dev/null
pwd
cd "$d"
read z <<END
heredoc-line
END
echo "z=$z"
read big <<END

END
echo "big=${#big}"
cd /
rm -rf "$d"
echo done
